import io
import json
from unittest.mock import patch
import openai_client

class Response(io.BytesIO):
    def __enter__(self):
        return self
    def __exit__(self, *args):
        self.close()

reply = {\"status\": \"completed\", \"output\": [{\"type\": \"message\", \"content\": [{\"type\": \"output_text\", \"text\": \"hello\"}, {\"type\": \"output_text\", \"text\": \" world\"}]}]}
def fake_urlopen(request, timeout):
    assert request.full_url == \"https://api.openai.com/v1/responses\"
    assert request.get_method() == \"POST\"
    assert request.get_header(\"Authorization\") == \"Bearer fake-key\"
    assert json.loads(request.data) == {\"model\": \"gpt-4.1-mini\", \"input\": \"sample\", \"store\": False}
    assert timeout == 60
    return Response(json.dumps(reply).encode())

with patch.object(openai_client, \"urlopen\", fake_urlopen):
    assert openai_client.send_prompt(\"sample\", api_key=\"fake-key\") == \"hello world\"
try:
    openai_client.send_prompt(\"\", api_key=\"fake-key\")
except ValueError:
    pass
else:
    raise AssertionError(\"Expected empty prompt rejection\")
print(\"Offline smoke tests passed\")
